# Accept legacy source labels without retaining them in presets or templates.
_ENGLISH_LABELS = {translated: english for english, translated in TRANSLATIONS["sv"].items()}


def localized_text(value, language: str) -> str:
    """Select supplied text without translating literal names or content.

    Args:
        value: Literal text or an English/Swedish translation mapping.
        language: Requested report language.

    Returns:
        The requested text, English fallback, or the original literal text.
    """
    if isinstance(value, dict):
        return value.get(language, value.get("en", next(iter(value.values()))))
    return value


def label(value, language: str) -> str:
    """Translate English interface labels or select supplied localized text.

    Args:
        value: English source label, legacy label, or explicit translation mapping.
        language: Requested report language.

    Returns:
        The translated interface label or supplied literal text.
    """
    if isinstance(value, dict):
        return localized_text(value, language)
    canonical = _ENGLISH_LABELS.get(value, value)
    return TRANSLATIONS.get(language, {}).get(canonical, canonical)
